from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import cm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Table, TableStyle, KeepTogether

OUT = 'LeaveFlow-Complete-User-Manual.pdf'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Cover',parent=styles['Title'],fontSize=30,leading=36,textColor=colors.HexColor('#14324a'),alignment=TA_CENTER,spaceAfter=20))
styles.add(ParagraphStyle(name='H1x',parent=styles['Heading1'],fontSize=18,leading=23,textColor=colors.HexColor('#14324a'),spaceBefore=14,spaceAfter=9))
styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],fontSize=13,leading=17,textColor=colors.HexColor('#1d5b7a'),spaceBefore=10,spaceAfter=5))
styles.add(ParagraphStyle(name='Bodyx',parent=styles['BodyText'],fontSize=9.4,leading=13,spaceAfter=6))
styles.add(ParagraphStyle(name='Smallx',parent=styles['BodyText'],fontSize=7.5,leading=10,spaceAfter=3))

def P(s,style='Bodyx'): return Paragraph(s,styles[style])
def table(rows,widths=None):
    t=Table([[P(str(c),'Smallx') for c in r] for r in rows],colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#14324a')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#b9c7d0')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f4f8fa')])]))
    return t
def heading(s,level=1): return P(s,'H1x' if level==1 else 'H2x')
def bullets(items): return [P('• '+x) for x in items]
def footer(canvas,doc):
    canvas.saveState(); canvas.setFont('Helvetica',8); canvas.setFillColor(colors.HexColor('#60717d')); canvas.drawString(2*cm,1.1*cm,'LeaveFlow Complete User Manual'); canvas.drawRightString(19*cm,1.1*cm,f'Page {doc.page}'); canvas.restoreState()

story=[]
story += [Spacer(1,5*cm),P('LeaveFlow','Cover'),P('Complete User Manual','Cover'),P('Employee, Manager, and Administrator Guide', 'Bodyx'),Spacer(1,1.5*cm),P('Version for the existing LeaveFlow application', 'Bodyx'),P('This manual uses fictional examples only. Never enter database records directly; use the application screens.', 'Bodyx'),PageBreak()]
story += [heading('Contents'),P('1. Getting started and permissions<br/>2. Employee workspace<br/>3. Manager workspace<br/>4. Administrator workspace<br/>5. End-to-end workflows<br/>6. Troubleshooting<br/>7. Database reference<br/>8. Glossary'),PageBreak()]
story += [heading('1. Getting started and permissions'),P('LeaveFlow is a role-aware leave management application. Sign in at <b>/login</b>. New people can use <b>/register</b>; registration accepts full name, work email, and an 8-100 character password and always creates an EMPLOYEE account. It does not create a manager, department assignment, or leave entitlement.'),heading('Role comparison',2),table([['Area','Employee','Manager','Administrator'],['Dashboard and profile','Own account','Own account + team summary','Organisation summary'],['Leave requests','Create/view/cancel own','Review direct reports','Review all permitted requests'],['Entitlements','View own','No adjustment','Assign and review'],['People/configuration','No','No','Manage permitted people/configuration'],['Audit and reports','No','No','View'],['Policy documents','Ask assistant','Ask assistant','Manage documents']],[4*cm,4*cm,4*cm,5*cm]),PageBreak()]
story += [heading('2. Employee workspace'),heading('Dashboard'),P('Overview shows My requests, Awaiting review, and Approved cards. Use Request leave to open Apply for leave. The dashboard also links to the HR policy assistant.'),heading('My profile'),P('Open My profile. Full name is required and can be saved. Work email, role, department, and employment assignments are informational; role and employment details are managed by HR.'),heading('Apply for leave'),P('Open Apply for leave. Select an active leave type, start date, end date, and enter the required reason. Dates cannot be in the past; end date cannot precede start date; the period must contain at least one non-weekend/non-holiday working day. The request must not overlap another request. A matching entitlement with enough remaining days is required.'),*bullets(['Example only: Rahul Sharma selects Annual Leave, 2030-06-10 to 2030-06-12, reason “Family travel”.','Sick Leave uses the same supported fields and validations; no additional medical field is implemented.','After submission the application is PENDING. The manager may receive a notification. Balance is not debited until approval.']),heading('History and self service'),P('My leave requests shows the employee’s own requests. Self service shows balances, balance history, upcoming holidays, and notifications. Mark read changes a notification state. A pending or approved own request can be cancelled only where the UI exposes that action; cancelling an approved request restores its working days and creates a balance transaction.'),heading('HR policy assistant'),P('Open HR policy assistant to view conversations and ask policy questions. A chat submission creates a conversation/message history. Answers use available policy evidence and may say evidence is insufficient. It does not approve leave.'),PageBreak()]
story += [heading('3. Manager workspace'),P('Managers see employee capabilities plus Management links. Team dashboards and lists are restricted to direct reports. Pending requests and team history use the manager relationship recorded for the employee.'),heading('Reviewing a request',2),*bullets(['Open Approvals or Pending requests and choose a direct report request.','Approve: the application becomes APPROVED; the applicant balance is debited, a balance transaction and audit record are created, and the applicant is notified.','Reject: enter a non-blank reviewer reason (maximum 500 characters). The request becomes REJECTED; balance is not debited and the applicant is notified.','A manager cannot self-review and cannot review an employee outside their direct-report scope.']),P('Example only: Priya Patil reviews Rahul’s three-day Annual Leave and approves it after confirming coverage. A rejection example: “Team coverage is unavailable for these dates; please choose an alternative.”'),PageBreak()]
story += [heading('4. Administrator workspace'),heading('Administration dashboard and people'),P('Administrators have all permitted management routes: Employee management, People & audit, Entitlements, Organisation setup, Reports, and Policy documents. Employee management can create/edit employee records; public registration does not grant those powers.'),heading('Leave entitlements'),P('Open Entitlements, select an employee, then inspect Current balances and Transaction history. To set an initial entitlement, choose an active leave type, enter Total days (0 or greater, increments of 0.5 in the UI), and enter a required reason up to 250 characters. Save entitlement sets the employee’s total remaining balance to that number, rather than adding a universal policy allowance.'),*bullets(['Example only: choose Rahul Sharma, Annual Leave, Total days 18, reason “Initial 2030 annual allocation”, then Save entitlement.','Success creates/updates leave_balance. If the amount changes, it also creates balance_transaction and audit_log records.','“No leave entitlement configured” means there is no balance row for the selected active leave type. A policy document saying “20 days” is not an entitlement until an administrator records one.']),heading('Organisation setup'),P('Organisation setup exposes configured departments, leave types, and holidays. Only use the actions shown on screen. Departments cannot be deleted while employees are assigned. Leave types are active/inactive; inactive types cannot be used for a new leave request.'),heading('People & audit, reports, policies'),P('People & audit displays employee and audit information. Audit events identify the actor, action, entity type, entity ID, and time. Reports display leave summaries/trends. Policy documents are administrator-only; ingestion changes policy data and embeddings, so use it only under an approved policy-management process.'),PageBreak()]
story += [heading('5. End-to-end workflows'),heading('New employee registration and login',2),P('1. Open Register. 2. Enter full name, valid email, password, and matching confirmation. 3. Submit. 4. On success, return to Login. Expected result: EMPLOYEE role only; no entitlement is automatically assigned.'),heading('Initial Annual Leave entitlement',2),P('Role: Administrator. Open Entitlements, choose employee and Annual Leave, enter the approved total and reason, then save. Expected result: current balance and transaction history update. This is the required step before a new employee can apply.'),heading('Employee request, review, and outcome',2),P('Role: Employee submits a valid date range/reason. Role: Manager opens pending requests, then approves or rejects. Approval debits balance; rejection requires a reason and does not debit balance. Employee checks History and Self service after the decision.'),heading('Other supported flows',2),P('Profile update: employee edits required full name and saves. Audit review: administrator opens People & audit. Unsupported policy question: ask the assistant; it may return insufficient evidence. AI chat persistence is expected. Cancellation, where available for the employee’s request, changes status and can restore an approved balance.'),PageBreak()]
story += [heading('6. Troubleshooting'),table([['Message or symptom','Supported cause','Correct next step'],['No leave entitlement configured','No leave_balance row for the employee and selected active type','Administrator assigns an entitlement in Entitlements.'],['Adjustment failed','The UI only displays the API message when a response is available; inspect browser Network and backend logs for status/message','Do not retry blindly. Record endpoint/status/body for an administrator.'],['Insufficient leave balance','Matching balance is below working days','Use other dates/type or request an authorised adjustment.'],['Invalid date range','Past start date or end before start','Choose valid non-past dates.'],['Leave must include a working day','Weekend/holiday only','Choose a working day.'],['Overlapping leave request exists','Existing request overlaps','Choose a non-overlapping period.'],['401 or session error','Missing/invalid session','Sign in again.'],['403 access denied','Role/scope does not permit action','Use the correct role; managers use direct reports only.'],['AI unavailable or insufficient evidence','AI/policy service unavailable or no accepted policy evidence','Retry later or contact policy administrator.']],[4.2*cm,6.2*cm,7.5*cm]),PageBreak()]
tables=[
('users','id; email; password (never displayed); role; full_name; department_id; manager_id','Account and role. Created by registration or admin employee creation.'),('department','id; name; code','Organisation unit. Used by employee assignment.'),('leave_type','id; name; active','Configured type. Active types appear in leave selection.'),('leave_balance','id; user_id; leave_type_id; remaining_days; version','Employee entitlement balance. Updated by entitlement, approval, and cancellation.'),('leave_applications','id; applicant_id; leave_type; start_date; end_date; working_days; status; reason; reviewer_note; version','Leave request created by employee; reviewed by manager/admin.'),('balance_transaction','id; balance_id; application_id; delta; reason; created_at','Immutable-looking balance activity from entitlement, approval, or cancellation.'),('holiday','id; holiday_date; name','Holiday used in working-day calculation.'),('audit_log','id; actor_id; action; entity_type; entity_id; created_at','Audit event generated by application actions.'),('notification','id; user_id; message; read_at; created_at','In-app notification; read state is updated by employee.'),('chat_conversations','id; user_id; title; created_at','AI conversation container.'),('chat_messages','id; conversation_id; role; content; citations; created_at','AI/user messages and citations.'),('pending_leave_confirmations','id; conversation_id; user_id; leave_type; start_date; end_date; reason; status; application_id; version','AI-assisted leave confirmation state, if used.'),('policy_documents','id; file_name; version; uploaded_by_id; created_at','Administrator uploaded policy document.'),('policy_chunks','id; document_id; chunk_index; source_page; content; vector_id','Searchable policy fragments, linked to document/embedding.'),('flyway_schema_history','installed_rank; version; description; type; script; checksum; installed_by; installed_on; execution_time; success','Migration bookkeeping; users do not edit it.')]
story += [heading('7. Database reference'),P('The application uses the frontend and APIs; do not manually insert rows. Primary keys are id fields unless stated. Foreign-key-like columns link users, balances, applications, documents, and conversations.'),table([['Table','Columns and purpose','Typical operation']]+[[a,b,c] for a,b,c in tables],[3.5*cm,9.2*cm,5.2*cm]),PageBreak()]
story += [heading('8. Relationships and glossary'),P('<b>Relationship:</b> a user may have a department and manager. A user has leave balances. A balance belongs to a leave type. An approved leave application debits its balance and creates a transaction. Audits and notifications are created automatically for relevant actions.'),heading('Glossary',2),*bullets(['Entitlement: a configured leave balance for one employee and leave type.','Working day: weekday that is not a configured holiday.','Pending/Approved/Rejected/Cancelled: leave request lifecycle statuses.','Direct report: employee whose manager is the reviewing manager.','Audit log: application record of who performed an action.','Policy evidence: document chunks accepted to support an AI answer.']),P('All fictional examples in this manual are illustrative and are not company policy or database data.')]

doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=1.5*cm,leftMargin=1.5*cm,topMargin=1.5*cm,bottomMargin=1.8*cm,title='LeaveFlow Complete User Manual',author='LeaveFlow')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
